"use strict";(self.webpackChunkgrc=self.webpackChunkgrc||[]).push([[88073],{88212:e=>{e.exports=JSON.parse('{"abstract":"KV caching significantly improves the efficiency of Large Language Model (LLM)\\ninference by storing attention states from previously processed tokens, enabling\\nfaster generation of subsequent tokens. However, as sequence length increases,\\nthe KV cache quickly becomes a major memory bottleneck. To address this, we\\npropose PagedEviction, a novel fine-grained, structured KV cache pruning strategy\\nthat enhances the memory efficiency of vLLM\'s PagedAttention. Unlike existing\\napproaches that rely on attention-based token importance or evict tokens across\\ndifferent vLLM pages, PagedEviction introduces an efficient block-wise eviction\\nalgorithm tailored for paged memory layouts. Our method integrates seamlessly\\nwith PagedAttention without requiring any modifications to its CUDA attention\\nkernels. We evaluate PagedEviction across Llama-3.1-8B-Instruct,\\nLlama-3.2-1B-Instruct, and Llama-3.2-3B-Instruct models on the LongBench\\nbenchmark suite, demonstrating improved memory usage with better accuracy than\\nbaselines on long context tasks.\\n","authors":["K. Chitty-Venkata","J. Ye","S. Raskar","A. Kougkas","X.-H. Sun","M. Emani","V. Vishwanath","B. Nicolae"],"date":"March, 2026","month":3,"year":2026,"links":{"bibtex":"http://cs.iit.edu/~scs/assets/files/chitty-venkata-2026-pagedeviction.bib","citation":"http://cs.iit.edu/~scs/assets/files/chitty-venkata-2026-pagedeviction.txt","pdf":"http://cs.iit.edu/~scs/assets/files/chitty-venkata-2026-pagedeviction.pdf"},"slug":"chitty-venkata-2026-pagedeviction-3f8a","tags":["KV Cache","Compression","LLM Inference Serving"],"title":"PagedEviction: Structured Block-wise KV Cache Pruning for Efficient Large Language Model Inference","type":"Conference","venue":"Findings of the Association for Computational Linguistics (EACL 2026)"}')}}]);